/**
 * Issue-list filter vocabulary shared by the URL codec, the Zod schema and
 * the repository. Group names and calendar dates stay meaningful in every
 * layer; see docs/adr/0009-issue-list-filters.md.
 */
import {
  CLOSED_ISSUE_STATUSES,
  ISSUE_STATUSES,
  type IssueStatus,
} from "@/types/issue";

/** URL and schema token for the signed-in user. Resolved by the service. */
export const ME_TOKEN = "me";

/** URL token for "no assignee". The codec stores this as `assigneeId: null`. */
export const UNASSIGNED_TOKEN = "none";

export const ARCHIVED_INCLUDED = "1";
export const ARCHIVED_ONLY = "only";

/** Statuses that are not closed. `status=open` expands to this list. */
export const OPEN_ISSUE_STATUSES: readonly IssueStatus[] = ISSUE_STATUSES.filter(
  (status) => !CLOSED_ISSUE_STATUSES.includes(status),
);

const CALENDAR_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** True for a real `YYYY-MM-DD` calendar date. Read as a UTC day. */
export function isCalendarDate(value: string): boolean {
  const match = CALENDAR_DATE.exec(value);
  if (match === null) return false;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = new Date(Date.UTC(year, month - 1, day));
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/**
 * Upper bound for a `due_before` value.
 * A calendar date includes the whole UTC day, so the bound is the next
 * midnight and the comparison stays strict-before. A timestamp is unchanged.
 */
export function dueBeforeCutoff(value: string): string {
  if (!isCalendarDate(value)) return value;
  const match = CALENDAR_DATE.exec(value);
  if (match === null) return value;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  return new Date(Date.UTC(year, month - 1, day + 1)).toISOString();
}

/**
 * Expands `open` / `closed` and drops tokens that are not a status or a group.
 * Concrete statuses pass through. Order follows `ISSUE_STATUSES`.
 */
export function expandStatusTokens(tokens: readonly string[]): IssueStatus[] {
  const expanded: IssueStatus[] = [];
  const seen = new Set<IssueStatus>();
  for (const token of tokens) {
    const members: readonly IssueStatus[] =
      token === "open"
        ? OPEN_ISSUE_STATUSES
        : token === "closed"
          ? CLOSED_ISSUE_STATUSES
          : (ISSUE_STATUSES as readonly string[]).includes(token)
            ? [token as IssueStatus]
            : [];
    for (const status of members) {
      if (seen.has(status)) continue;
      seen.add(status);
      expanded.push(status);
    }
  }
  return expanded;
}

