  ISSUE_STATUSES,
  type IssueStatus,
} from "@/types/issue";

/** URL and schema token for the signed-in user. Resolved by the service. */
export const ME_TOKEN = "me";

/** URL token for "no assignee". The codec stores this as `assigneeId: null`. */
export const UNASSIGNED_TOKEN = "none";

export const ARCHIVED_INCLUDED = "1";
export const ARCHIVED_ONLY = "only";

/** Statuses that are not closed. `status=open` expands to this list. */
export const OPEN_ISSUE_STATUSES: readonly IssueStatus[] = ISSUE_STATUSES.filter(
  (status) => !CLOSED_ISSUE_STATUSES.includes(status),
);

const CALENDAR_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** True for a real `YYYY-MM-DD` calendar date. Read as a UTC day. */
export function isCalendarDate(value: string): boolean {
  const match = CALENDAR_DATE.exec(value);
  if (match === null) return false;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = new Date(Date.UTC(year, month - 1, day));
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

