import { z } from "zod";
import { isCalendarDate } from "@/lib/issue-filter";
import type { IssuePriority, IssueStatus } from "@/types/issue";
import {
  archiveScopeSchema,
  isoTimestampSchema,
  issueIdSchema,
  labelIdSchema,
  orgIdSchema,
  pageRequestSchema,
  projectIdSchema,
  userIdSchema,
} from "./common";

export const issuePrioritySchema = z.enum([
  "none",
  "low",
  "medium",
  "high",
  "urgent",
]);

/** A concrete status or one of the groups `open` and `closed`. */
export const issueStatusTokenSchema = z.enum([
  "backlog",
  "todo",
  "in_progress",
  "in_review",
  "done",
  "canceled",
  "open",
  "closed",
]);

/** Splits a comma-separated query value into the list the filter schema stores. */
function asTokenList(value: unknown): unknown {
  if (value === undefined || value === null || value === "") return undefined;
  const parts = Array.isArray(value) ? value : [value];
  const tokens = parts.flatMap((part) =>
    typeof part === "string"
      ? part
          .split(",")
          .map((item) => item.trim())
          .filter((item) => item.length > 0)
      : [],
  );
  return tokens.length > 0 ? tokens : undefined;
}

export const issueStatusFilterSchema = z.preprocess(
  asTokenList,
  z.array(issueStatusTokenSchema).optional(),
);

export const issuePriorityFilterSchema = z.preprocess(
  asTokenList,
  z.array(issuePrioritySchema).optional(),
);

export const labelIdFilterSchema = z.preprocess(
  asTokenList,
  z.array(labelIdSchema).optional(),
);

/** A user id, `"me"` (the signed-in user), `"none"` / null (unassigned). */
export const assigneeFilterSchema = z
  .union([
    z.literal("me"),
    z.literal("none").transform(() => null),
    z.null(),
    userIdSchema,
  ])
  .optional();

/** A user id or `"me"`. Omitting the field means "do not filter". */
export const authorFilterSchema = z
  .union([z.literal("me"), userIdSchema])
  .optional();

/**
 * `due_before`: a UTC calendar date (`YYYY-MM-DD`, that whole day included)
 * or a full ISO-8601 timestamp (strictly before that instant).
 */
export const dueBeforeSchema = z.union([
  isoTimestampSchema,
  z.string().refine(isCalendarDate, "must be YYYY-MM-DD or an ISO-8601 timestamp"),
]);

export const archivedFilterSchema = z.enum(["1", "only"]).optional();

