/** Adapts a Next.js `searchParams` record to the codec's `get` shape. */
export function readSearchParams(
  search: ReadableParams | Record<string, string | string[] | undefined>,
): ReadableParams {
  if ("get" in search && typeof search.get === "function") {
    return search;
  }
  const record = search as Record<string, string | string[] | undefined>;
  return {
    get(name: string): string | null {
      const value = record[name];
      if (value === undefined) return null;
      return Array.isArray(value) ? value.join(",") : value;
    },
  };
}

function actorToken(
  raw: string,
): UserId | typeof ME_TOKEN {
  return raw === ME_TOKEN ? ME_TOKEN : (raw as UserId);
}

export function parseIssueFilterParams(params: ReadableParams): IssueFilter {
  const statuses = expandStatusTokens(splitList(params.get("status")));
  const priorities = splitList(params.get("priority")).filter(
    (value): value is IssuePriority =>
      ISSUE_PRIORITIES.includes(value as IssuePriority),
  );
  const labelIds = splitList(params.get("label")) as readonly LabelId[];
  const project = params.get("project");
  const assignee = params.get("assignee");
  const author = params.get("author");
  const query = params.get("q");
  const dueRaw = params.get("due_before");
  const dueParsed =
    dueRaw === null || dueRaw.length === 0
      ? null
      : dueBeforeSchema.safeParse(dueRaw);
  const archived = params.get("archived");

  const filter: IssueFilter = {
    ...(project !== null && project.length > 0
      ? { projectId: project as ProjectId }
      : {}),
    ...(statuses.length > 0 ? { status: statuses } : {}),
    ...(priorities.length > 0 ? { priority: priorities } : {}),
    ...(assignee !== null && assignee.length > 0
      ? {
          assigneeId:
            assignee === UNASSIGNED_TOKEN ? null : actorToken(assignee),
        }
      : {}),
    ...(author !== null && author.length > 0
      ? { authorId: actorToken(author) }
      : {}),
    ...(labelIds.length > 0 ? { labelIds } : {}),
    ...(query !== null && query.length > 0 ? { query } : {}),
    ...(dueParsed !== null && dueParsed.success
      ? { dueBefore: dueParsed.data }
      : {}),
    ...(archived === ARCHIVED_INCLUDED ? { includeArchived: true } : {}),
    ...(archived === ARCHIVED_ONLY ? { archivedOnly: true } : {}),
  };

  return filter;
}

