/**
 * Nav segments are path pieces, except a filter link such as
 * `issues?assignee=me`, whose query must survive as a query string.
 */
function hrefForSegment(orgSlug: string, segment: string): string {
  const queryAt = segment.indexOf("?");
  if (queryAt === -1) return orgPath(orgSlug, segment);
  const path = segment.slice(0, queryAt);
  const search = new URLSearchParams(segment.slice(queryAt + 1));
  const params: Record<string, string> = {};
  search.forEach((value, key) => {
    params[key] = value;
  });
  return withSearchParams(orgPath(orgSlug, path), params);
}

