export function toggleStatus(
  filter: IssueFilter,
  status: IssueStatus,
): IssueFilter {
  const current = filter.status ?? [];
  const next = current.includes(status)
    ? current.filter((value) => value !== status)
    : [...current, status];
  const { status: _dropped, ...rest } = filter;
  return next.length === 0 ? rest : { ...rest, status: next };
}

input.new_string:
/** Adds or removes one status without disturbing the other dimensions. */
export function toggleStatus(
  filter: IssueFilter,
  status: IssueStatus,
): IssueFilter {
  const current = filter.status ?? [];
  const next = current.includes(status)
    ? current.filter((value) => value !== status)
    : [...current, status];
  const { status: _dropped, ...rest } = filter;
  return next.length === 0 ? rest : { ...rest, status: next };
}

/** True when the status filter is exactly `expected`, ignoring order. */
function isStatusSet(
  filter: IssueFilter,
  expected: readonly IssueStatus[],
): boolean {
  const current = filter.status ?? [];
  if (current.length !== expected.length) return false;
  return expected.every((status) => current.includes(status));
}

/**
 * Selects a status group (`open` or `closed`) in one step. Clicking the group
 * that is already selected clears the status filter.
 */
export function toggleStatusGroup(
  filter: IssueFilter,
  expected: readonly IssueStatus[],
): IssueFilter {
  const { status: _dropped, ...rest } = filter;
  if (isStatusSet(filter, expected)) return rest;
  return { ...rest, status: [...expected] };
}

