import { parseIssueFilterParams } from "@/hooks/issue-filter-params";
import { exportIssuesSchema, issueFilterSchema } from "@/schemas/issue";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as issueService from "@/server/services/issue-service";
import { createTenant, issueInput, useTemporaryDatabase } from "@/tests/server/_support/fixtures";

function params(query: string): URLSearchParams {
  return new URLSearchParams(query);
}

const cleanup = await useTemporaryDatabase();
const tenant = await createTenant("filter-check");
const orgId = tenant.org.id;
const projectId = tenant.project.id;

const bug = await labelRepo.insertLabel({
  orgId,
  name: "bug",
  color: "#ef4444",
  description: null,
});
const regression = await labelRepo.insertLabel({
  orgId,
  name: "regression",
  color: "#f59e0b",
  description: null,
});

async function add(overrides: Record<string, unknown>) {
  const number = await issueRepo.nextIssueNumber(orgId, projectId);
  return issueRepo.insertIssue(
    {
      ...issueInput(orgId, projectId, {}),
      ...overrides,
    } as never,
    tenant.userIds.owner,
    number,
  );
}

const both = await add({
  title: "both labels",
  assigneeId: tenant.userIds.member,
  status: "todo",
  labelIds: [bug.id, regression.id],
  dueAt: "2026-03-15T18:00:00.000Z",
});
const one = await add({
  title: "one label",
  assigneeId: null,
  status: "done",
  labelIds: [bug.id],
  dueAt: "2026-03-15T08:00:00.000Z",
});
const later = await add({
  title: "later",
  assigneeId: tenant.userIds.member,
  status: "backlog",
  labelIds: [bug.id, regression.id],
  dueAt: "2026-03-16T00:00:00.000Z",
});
const noDue = await add({
  title: "no due",
  assigneeId: tenant.userIds.member,
  status: "in_progress",
  labelIds: [],
  dueAt: null,
});
const archived = await add({
  title: "archived open",
  assigneeId: tenant.userIds.member,
  status: "todo",
  labelIds: [],
  dueAt: null,
});
await issueRepo.archiveIssue(orgId, archived.id);

const base = { orgId, limit: 50, cursor: null as null };

const labels = await issueRepo.listIssues({
  ...base,
  labelIds: [bug.id, regression.id],
});
console.log(
  "labels all-of",
  labels.items.map((i) => i.title),
  "total",
  labels.total,
);

const unassigned = await issueRepo.listIssues({ ...base, assigneeId: null });
console.log(
  "unassigned",
  unassigned.items.map((i) => i.title),
  "total",
  unassigned.total,
);

const byDate = await issueRepo.listIssues({ ...base, dueBefore: "2026-03-15" });
console.log(
  "due date",
  byDate.items.map((i) => i.title),
  "total",
  byDate.total,
);

const byStamp = await issueRepo.listIssues({
  ...base,
  dueBefore: "2026-03-15T12:00:00.000Z",
});
console.log(
  "due stamp",
  byStamp.items.map((i) => i.title),
  "total",
  byStamp.total,
);

const open = await issueRepo.listIssues({ ...base, status: ["open"] as never });
console.log(
  "open",
  open.items.map((i) => i.title),
  "total",
  open.total,
);

const only = await issueRepo.listIssues({ ...base, archivedOnly: true });
console.log(
  "archived only",
  only.items.map((i) => i.title),
  "total",
  only.total,
);

const mixed = await issueRepo.listIssues({ ...base, includeArchived: true });
console.log("include archived total", mixed.total, "live+archived titles", mixed.items.length);

const parsed = issueFilterSchema.parse({
  orgId,
  status: "open",
  assigneeId: "me",
  dueBefore: "2026-03-15",
  archived: "only",
});
console.log("schema", parsed.status, parsed.assigneeId, parsed.dueBefore, parsed.archived);

const refused = issueFilterSchema.safeParse({ orgId, status: "nope" });
console.log("refused nope", refused.success);

const exported = exportIssuesSchema.safeParse({
  orgId,
  status: "open",
  format: "csv",
});
console.log("export open", exported.success, exported.success && exported.data.status);

const codec = parseIssueFilterParams(
  params("assignee=me&author=me&status=open,done&due_before=2026-03-15&archived=only&label=a,b"),
);
console.log("codec", codec);

const mePage = await issueService.listIssues(tenant.actors.member, {
  orgId,
  assigneeId: "me",
  status: ["open"],
  limit: 50,
});
console.log(
  "service me+open",
  mePage.items.map((i) => i.title),
  "total",
  mePage.total,
);

console.log("ids", { both: both.id, one: one.id, later: later.id, noDue: noDue.id, archived: archived.id });
cleanup();

