import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { parseIssueFilterParams } from "@/hooks/issue-filter-params";
import { exportIssuesSchema, issueFilterSchema } from "@/schemas/issue";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as issueService from "@/server/services/issue-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Tenant } from "./server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("filter-check");
});

afterAll(() => {
  cleanup();
});

describe("tmp filter check", () => {
  it("matches the vocabulary", async () => {
    const orgId = tenant.org.id;
    const projectId = tenant.project.id;
    const bug = await labelRepo.insertLabel({
      orgId,
      name: "bug",
      color: "#ef4444",
      description: null,
    });
    const regression = await labelRepo.insertLabel({
      orgId,
      name: "regression",
      color: "#f59e0b",
      description: null,
    });

    async function add(overrides: {
      title: string;
      assigneeId?: (typeof tenant.userIds)["member"] | null;
      status?: "backlog" | "todo" | "in_progress" | "done";
      labelIds?: string[];
      dueAt?: string | null;
    }) {
      const number = await issueRepo.nextIssueNumber(orgId, projectId);
      return issueRepo.insertIssue(
        {
          ...issueInput(orgId, projectId, {
            title: overrides.title,
            assigneeId: overrides.assigneeId ?? null,
            dueAt: overrides.dueAt ?? null,
          }),
          status: overrides.status ?? "backlog",
          labelIds: (overrides.labelIds ?? []) as never,
        },
        tenant.userIds.owner,
        number,
      );
    }

    const both = await add({
      title: "both labels",
      assigneeId: tenant.userIds.member,
      status: "todo",
      labelIds: [bug.id, regression.id],
      dueAt: "2026-03-15T18:00:00.000Z",
    });
    await add({
      title: "one label",
      assigneeId: null,
      status: "done",
      labelIds: [bug.id],
      dueAt: "2026-03-15T08:00:00.000Z",
    });
    await add({
      title: "later",
      assigneeId: tenant.userIds.member,
      status: "backlog",
      labelIds: [bug.id, regression.id],
      dueAt: "2026-03-16T00:00:00.000Z",
    });
    await add({
      title: "no due",
      assigneeId: tenant.userIds.member,
      status: "in_progress",
      dueAt: null,
    });
    const archived = await add({
      title: "archived open",
      assigneeId: tenant.userIds.member,
      status: "todo",
    });
    await issueRepo.archiveIssue(orgId, archived.id);

    const base = { orgId, limit: 50, cursor: null as null };

    const labels = await issueRepo.listIssues({
      ...base,
      labelIds: [bug.id, regression.id],
    });
    expect(labels.items.map((issue) => issue.id).sort()).toEqual(
      [both.id].sort(),
    );
    expect(labels.total).toBe(labels.items.length);

    const unassigned = await issueRepo.listIssues({ ...base, assigneeId: null });
    expect(unassigned.items.map((issue) => issue.title)).toEqual(["one label"]);
    expect(unassigned.total).toBe(1);

    const byDate = await issueRepo.listIssues({ ...base, dueBefore: "2026-03-15" });
    expect(byDate.items.map((issue) => issue.title).sort()).toEqual(
      ["both labels", "one label"].sort(),
    );
    expect(byDate.total).toBe(2);

    const byStamp = await issueRepo.listIssues({
      ...base,
      dueBefore: "2026-03-15T12:00:00.000Z",
    });
    expect(byStamp.items.map((issue) => issue.title)).toEqual(["one label"]);

    const open = await issueRepo.listIssues({
      ...base,
      status: ["open"] as never,
    });
    expect(open.items.map((issue) => issue.title).sort()).toEqual(
      ["both labels", "later", "no due"].sort(),
    );
    expect(open.total).toBe(3);

    const only = await issueRepo.listIssues({ ...base, archivedOnly: true });
    expect(only.items.map((issue) => issue.id)).toEqual([archived.id]);
    expect(only.total).toBe(1);

    const parsed = issueFilterSchema.parse({
      orgId,
      status: "open",
      assigneeId: "me",
      authorId: "me",
      dueBefore: "2026-03-15",
      archived: "only",
    });
    expect(parsed.status).toEqual(["open"]);
    expect(parsed.assigneeId).toBe("me");
    expect(parsed.authorId).toBe("me");
    expect(parsed.dueBefore).toBe("2026-03-15");
    expect(parsed.archived).toBe("only");
    expect(issueFilterSchema.safeParse({ orgId, status: "nope" }).success).toBe(false);
    expect(issueFilterSchema.parse({ orgId, assigneeId: "none" }).assigneeId).toBeNull();

    const exported = exportIssuesSchema.parse({ orgId, status: "open" });
    expect(exported.status).toEqual(["open"]);

    const codec = parseIssueFilterParams(
      new URLSearchParams(
        "assignee=me&author=me&status=open&due_before=2026-03-15&archived=only",
      ),
    );
    expect(codec.assigneeId).toBe("me");
    expect(codec.authorId).toBe("me");
    expect(codec.status).toEqual(["backlog", "todo", "in_progress", "in_review"]);
    expect(codec.dueBefore).toBe("2026-03-15");
    expect(codec.archivedOnly).toBe(true);
    expect(codec.includeArchived).toBeUndefined();

    const mePage = await issueService.listIssues(tenant.actors.member, {
      orgId,
      assigneeId: "me",
      status: ["open"],
      limit: 50,
    });
    expect(mePage.items.map((issue) => issue.title).sort()).toEqual(
      ["both labels", "no due"].sort(),
    );
    expect(mePage.total).toBe(2);
  });
});

